{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C40"],
      "claim": "Morphine, the closest structural analogue (same morphinan scaffold; codeine is its 3-methyl ether), has an absolute oral bioavailability of 23.8% in humans, directly supporting F≥20% for codeine.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Noscapine, an opium alkaloid with N-methyl and methoxy groups, shows 30% absolute oral bioavailability in healthy volunteers, supporting that this alkaloid class can exceed the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Ketobemidone, a small basic opioid, has a mean oral bioavailability of 34% (range 17–62%) in patients, providing additional support for F≥20% in small moderately lipophilic opioids.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Naltrexone, a morphinan with N-cyclopropylmethyl and 6-keto, has low oral bioavailability (5–6%) in healthy volunteers, indicating that some morphinans fall below 20% due to extensive first-pass metabolism; this is not directly transferable to codeine because codeine has N-methyl and 3-methoxy.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C04"],
      "claim": "ThH, a morphinan derivative with N-cyclopropylmethyl and bulky substituents, has very low oral bioavailability in humans, but its structural modifications are not shared by codeine.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C25"],
      "claim": "Tetrabenazine has very low oral systemic availability (4.9%) in patients, but its benzoquinolizine scaffold and metabolic profile are not representative of codeine.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "Codeine is a small, moderately lipophilic morphinan with a 3-methoxy group that avoids phenol glucuronidation and an N-methyl group. The closest structural analogue morphine shows absolute oral bioavailability of 20–45% in humans, and other small opioids (noscapine, ketobemidone) show F around 30–34%. Although some morphinans (naltrexone, ThH) and unrelated alkaloids (tetrabenazine) have low F, their specific structural/metabolic liabilities are not shared by codeine. Overall, F≥20% is well supported.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement for codeine in the provided evidence.",
    "No data on codeine-specific first-pass metabolism (CYP2D6 O-demethylation, glucuronidation) in the evidence set.",
    "M6G (polar glucuronide) and cepharanthine (large bisbenzylisoquinoline) are not applicable to codeine due to major physicochemical differences.",
    "Food effect for codeine is not addressed, though the query condition is fasted."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

